CREATE TABLE IF NOT EXISTS public.affiliate_commissions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE, affiliate_id uuid NOT NULL REFERENCES public.affiliates(id) ON DELETE RESTRICT, referral_id uuid NOT NULL UNIQUE REFERENCES public.affiliate_referrals(id) ON DELETE RESTRICT, sale_id uuid REFERENCES public.sales(id) ON DELETE SET NULL, amount numeric NOT NULL CHECK (amount > 0), currency text NOT NULL DEFAULT 'KES', status text NOT NULL DEFAULT 'PENDING', earned_at timestamptz NOT NULL DEFAULT now(), approved_at timestamptz, approved_by uuid, paid_at timestamptz, notes text);